```
func validatePlugins(plugins *config.Plugins) error {
	if plugins == nil {
		return nil
	}

	validate := func(pgs *config.PluginSet, setName string) error {
		if pgs == nil {
			return
		}
               pgSet := sets.NewString()
		for _, pg := range pgs.Enabled {
                        if pgSet.Has(pg.Name) {
                          return fmt.Errorf("duplicate %q plugin in %q plugin set", pg.Name, setName)
                        }
			pgSet.Insert(pg.Name)
		}
	}
	if err := validate(plugins.QueueSort, "QueueSort"); err != nil {
            return error
        }
	if err:= validate(plugins.PreFilter, "PreFilter"); err != nil {
            return error
        }
        .....
	return nil
}
